	@Override
	public System executeService(GeneralRequest request) throws Exception {
		
		if (request.getResource_Details().getSiteID().equals("RR") && (!(StringUtils.isEmpty(request.getResource_Details().getSite_Code())) && buildMap.containsKey(request.getResource_Details().getSite_Code()))) {
			request.getResource_Details().setBuild_ID(buildMap.get(request.getResource_Details().getSite_Code()));
		}

		EmployeeLog employeeLog = new EmployeeLog();
		employeeLog.setSystemName(ServiceDataEnum.RARS.name());
		employeeLog.setEmpId(request.getResource_Details().getWorkerCode());	
		employeeLog.setTransId(request.getClientTxnId());
		employeeLog.setTransMode(request.getResource_Details().getTransMode());
		employeeLog.setApprovalStatus(request.getResource_Details().getApproval_Status());
		
		System response = new System();
		response.setSystemName(ServiceDataEnum.RARS.name());
		
		if (!appConfig.getRarsFields().isDamStatus()) {
			
			String cmnMessage = CommonsMessage.getErrorJsonResponseMessage("CWMS_Dataprovison_ERR","027");
			ObjectMapper objectMapper = new ObjectMapper();

			JsonNode jsonNode = objectMapper.readTree(cmnMessage);
			String message = jsonNode.get("msg").asText();
			String modifiedMessage = message.trim();
			((ObjectNode) jsonNode).put("message", modifiedMessage);
			
            response.setSystemMsg(modifiedMessage);
            response.setSystemStatus(CwmsConstants.sysStatusF);
            return response;
        }
		
		String responseStatus = "";

		try {
			switch (request.getResource_Details().getTransMode()) {
			case "ADD":
			case "MOD":
				responseStatus = insertRecord(request, employeeLog);
				break;
			case "TER":
				responseStatus = terminateRecord(request, employeeLog);
				break;

			}
		} catch (Exception e) {
			LogWrapper.error(getClass(), e.getMessage());
			response.setSystemStatus(AppConstant.sysStatusF);
		}
		
		if (responseStatus.equalsIgnoreCase("S")) {
			response.setSystemStatus(AppConstant.sysStatusS);
		}
		else {
			response.setSystemStatus(AppConstant.sysStatusF);
		}
		
		try {
			employeeLog.setResponse(responseStatus);
			employeeLog.setResponseTime(LocalDateTime.now());
			employeeLog.setStatus(response.getSystemStatus());
			
			employeeLogRepo.save(employeeLog);
		}
		catch (Exception e) {
			LogWrapper.error(getClass(), e.getLocalizedMessage());
		}

		return response;
	}

	private String terminateRecord(GeneralRequest request, EmployeeLog employeeLog) throws Exception {
		
		String rarsBodyPart = commonUtlis.jsonNodeResponse(appConfig.getRarsFields().getDam_requestHeader()).get("terminate").asText();		
	
		HttpHeaders headers = commonUtlis.headers(commonUtlis.jsonNodeResponse(appConfig.getRarsFields().getDamHeaders()).get("terminate"));

		String rsrsRequest = rarsBodyPart.replaceAll("@IdentityCode",
				request.getResource_Details().getPrmID() == null ? request.getResource_Details().getWorkerCode()
						: request.getResource_Details().getPrmID());
		
		employeeLog.setRequest(rsrsRequest);
		employeeLog.setRequestTime(LocalDateTime.now());

		String url = appConfig.getRarsFields().getDamProtocol()+CwmsConstants.protocolSeperator+appConfig.getRarsFields().getDamserverIpUrl()
                +appConfig.getRarsFields().getDamEndpoint();
		String rarsResponse = restTemplate.exchange(url, HttpMethod.POST,
				new HttpEntity<String>(rsrsRequest, headers), String.class).getBody();

		LogWrapper.info(getClass(), rarsResponse);

		DocumentBuilder builder = DocumentBuilderFactory.newInstance().newDocumentBuilder();
		InputSource src = new InputSource();
		src.setCharacterStream(new StringReader(rarsResponse));

		Document doc = builder.parse(src);

		String responseStatus = doc.getElementsByTagName("DeActiveResult").item(0).getTextContent();

		LogWrapper.info(getClass(), "rsrs Response Status " + responseStatus);
		
		return responseStatus;

	}

	private String insertRecord(GeneralRequest request, EmployeeLog employeeLog) throws Exception {
		
		String rarsBodyPart = commonUtlis.jsonNodeResponse(appConfig.getRarsFields().getDam_requestHeader()).get("insert").asText();

		
		Add rarsRequestObject = new Add();
		rarsRequestObject.fromGeneralRequest(request);

		XmlMapper xmlMapper = new XmlMapper();
		String rsrsRequest = xmlMapper.writeValueAsString(rarsRequestObject);
		rsrsRequest = rsrsRequest.replaceAll("<", "<tem:").replaceAll("<tem:/", "</tem:");

		rsrsRequest = rarsBodyPart.replaceAll("@RequestBody", rsrsRequest);
		
		employeeLog.setRequest(rsrsRequest);
		employeeLog.setRequestTime(LocalDateTime.now());

		HttpHeaders headers = commonUtlis.headers(commonUtlis.jsonNodeResponse(appConfig.getRarsFields().getDamHeaders()).get("insert"));
		

		   String url = appConfig.getRarsFields().getDamProtocol()+CwmsConstants.protocolSeperator+appConfig.getRarsFields().getDamserverIpUrl()
	                +appConfig.getRarsFields().getDamEndpoint();

		String rarsResponse = restTemplate.exchange(url, HttpMethod.POST,
				new HttpEntity<String>(rsrsRequest, headers), String.class).getBody();

		LogWrapper.info(getClass(), rarsResponse);

		DocumentBuilder builder = DocumentBuilderFactory.newInstance().newDocumentBuilder();
		InputSource src = new InputSource();
		src.setCharacterStream(new StringReader(rarsResponse));

		Document doc = builder.parse(src);

		String responseStatus = doc.getElementsByTagName("AddResult").item(0).getTextContent();

		LogWrapper.info(getClass(), "rsrs Response Status " + responseStatus);
		
		return responseStatus;

	}

